{"function": "() => {
    const section = document.getElementById('id1');
    if (!section) return 'Not found';
    // Helper to convert section to markdown-like text
    function toMarkdown(node, depth = 0) {
        let result = '';
        // Process child nodes
        for (let child of node.childNodes) {
            if (child.nodeType === Node.ELEMENT_NODE) {
                const tag = child.tagName.toLowerCase();
                if (tag.startsWith('h')) {
                    const level = parseInt(tag.substring(1));
                    const headingText = child.textContent.trim();
                    result += '#'.repeat(level) + ' ' + headingText + '\n';
                    // recursively process children (but headings may have nested sections?)
                } else if (tag === 'p') {
                    result += child.textContent.trim() + '\n\n';
                } else if (tag === 'ul' || tag === 'ol') {
                    const items = child.querySelectorAll('li');
                    for (let li of items) {
                        result += '- ' + li.textContent.trim() + '\n';
                    }
                    result += '\n';
                } else if (tag === 'code') {
                    result += '`' + child.textContent + '`';
                } else if (tag === 'a') {
                    // skip links for brevity
                    result += child.textContent;
                } else {
                    // recursively process
                    result += toMarkdown(child, depth + 1);
                }
            } else if (child.nodeType === Node.TEXT_NODE) {
                const text = child.textContent.trim();
                if (text) result += text + ' ';
            }
        }
        return result;
    }
    return toMarkdown(section);
}"}

